            if wanted:
                have = set(tag_store.get(contact["contact_id"], []))
                if tag_mode == "all" and not set(wanted) <= have:
                    return False
                if tag_mode == "any" and not (set(wanted) & have):
                    return False
            return True

        history_store = data.get("stage_history", {})
        records = []
        for opportunity in data.get("opportunities", {}).values():
            contact = contacts.get(opportunity["contact_id"])
            if contact is None or not matches(contact):
                continue
            for entry in history_store.get(opportunity["opportunity_id"], []):
                # Only saved history with a non-null date inside the inclusive
                # range counts; nothing is back-filled for deals without records.
                if entry["on"] is None or not start_on <= entry["on"] <= end_on:
                    continue
                records.append({"opportunity_id": opportunity["opportunity_id"],
                                "contact_id": contact["contact_id"],
                                "title": opportunity["title"],
                                "organization": contact["organization"],
                                "from_stage": entry["from_stage"],
                                "to_stage": entry["to_stage"],
                                "on": entry["on"]})
        # Ascending date, then opportunity id code point; the stable sort keeps
        # save order among entries sharing the same day and opportunity.
        records.sort(key=lambda record: (record["on"], record["opportunity_id"]))

        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(("opportunity_id", "contact_id", "title", "organization",
                         "from_stage", "to_stage", "on"))
        for record in records:
            writer.writerow((record["opportunity_id"], record["contact_id"], record["title"],
                             record["organization"], record["from_stage"], record["to_stage"],
                             record["on"]))
        return {"records": records, "csv": buffer.getvalue()}

    def timeline(self, contact_id):
        data = self._read()
        if contact_id not in data.get("contacts", {}):
            raise ValueError("unknown contact")
        return sorted((r for r in data.get("followups", []) if r["contact_id"] == contact_id), key=lambda r: r["on"])

    def inactive_contacts(self, as_of, inactive_days, organization=None, tags=None, tag_mode="all"):
        as_of = calendar_day(as_of, "as_of")
        # type(...) is int rejects bools, which are ints in Python but never a day count.
        inactive_days = positive(inactive_days, "inactive_days")
        if organization is not None and not isinstance(organization, str):
            raise ValueError("organization must be a string")
        wanted = [] if tags is None else normalize_tags(tags)
        if tag_mode not in ("all", "any"):
            raise ValueError("tag_mode must be 'all' or 'any'")
        data = self._read()
        contacts = data.get("contacts", {})
        tag_store = data.get("tags", {})
        org_key = organization.strip().casefold() if organization is not None else None

        def matches(contact):
            if org_key is not None and contact["organization"].casefold() != org_key:
                return False
            if wanted:
                have = set(tag_store.get(contact["contact_id"], []))
                if tag_mode == "all" and not set(wanted) <= have:
                    return False
                if tag_mode == "any" and not (set(wanted) & have):
                    return False
            return True

        cutoff = date.fromisoformat(as_of)
        # Only records on/before as_of count; scanning in save order and replacing
        # on an equal or later day leaves the last saved same-day entry as the latest.
        latest = {}
        for entry in data.get("followups", []):
            if entry["on"] <= as_of:
                current = latest.get(entry["contact_id"])
                if current is None or entry["on"] >= current[0]:
                    latest[entry["contact_id"]] = (entry["on"], dict(entry))

        never, idle_rows = [], []
        for contact in contacts.values():
            if not matches(contact):
                continue
            current = latest.get(contact["contact_id"])
            if current is None:
                # Never followed up, or only future records: no record qualifies by as_of.
                never.append({"contact": dict(contact), "last_followup": None, "idle_days": None})
            else:
                on, entry = current
                idle_days = (cutoff - date.fromisoformat(on)).days
                if idle_days >= inactive_days:
                    idle_rows.append({"contact": dict(contact), "last_followup": entry,
                                      "idle_days": idle_days})

        never.sort(key=lambda row: row["contact"]["contact_id"])
        idle_rows.sort(key=lambda row: (-row["idle_days"], row["contact"]["contact_id"]))
        return never + idle_rows

import argparse
import json
from pathlib import Path
import sys
import tempfile
from . import ContactFlow

ACTIONS = {'add': 'add_contact', 'update-contact': 'update_contact', 'update-contacts': 'update_contacts', 'follow-up': 'follow_up', 'find': 'find', 'duplicate-candidates': 'duplicate_candidates', 'timeline': 'timeline', 'merge': 'merge_contacts', 'set-tags': 'set_tags', 'get-tags': 'get_tags', 'import-contacts': 'import_contacts', 'import-followups': 'import_followups', 'import-opportunities': 'import_opportunities', 'add-opportunity': 'add_opportunity', 'set-stage': 'set_stage', 'stage-history': 'stage_history', 'stage-change-report': 'stage_change_report', 'find-opportunities': 'find_opportunities', 'transfer-opportunities': 'transfer_opportunities', 'funnel-report': 'funnel_report', 'set-opportunity-amount': 'set_opportunity_amount', 'opportunity-amount-report': 'opportunity_amount_report', 'set-reminder': 'set_reminder', 'clear-reminder': 'clear_reminder', 'complete-reminder': 'complete_reminder', 'due-reminders': 'due_reminders', 'followup-report': 'followup_report', 'inactive-contacts': 'inactive_contacts'}

def samples(name):
    return json.loads((Path(__file__).resolve().parent.parent / "examples" / name).read_text(encoding="utf-8"))

def demo(app):
    for contact in samples("contacts.json"):
        app.add_contact(**contact)
    for entry in samples("followups.json"):
        app.follow_up(**entry)
    return app.timeline("C-001")

def main(argv=None):
    parser = argparse.ArgumentParser(description="客户跟进工作台")
    parser.add_argument("--root", required=True, help="local data directory")
    parser.add_argument("action", choices=[*ACTIONS, "demo"])
    parser.add_argument("input", nargs="?", help="UTF-8 JSON object, or array of objects, containing API arguments")
    args = parser.parse_args(argv)
    try:
        if args.action == "demo":
            # Sample operations run in a fresh child directory and never overwrite user's data.
            Path(args.root).mkdir(parents=True, exist_ok=True)
            with tempfile.TemporaryDirectory(prefix="sample-", dir=args.root) as location:
                value = demo(ContactFlow(location))
        else:
            payload = json.loads(Path(args.input).read_text(encoding="utf-8")) if args.input else {}
            app = ContactFlow(args.root)
            method = getattr(app, ACTIONS[args.action])
            if isinstance(payload, list):
                value = []
                for row in payload:
                    if not isinstance(row, dict):
                        raise ValueError("each input must be an object")
                    value.append(method(**row))
            elif isinstance(payload, dict):
                value = method(**payload)
            else:
                raise ValueError("input must be an object or array")
        print(json.dumps(value, ensure_ascii=False, sort_keys=True))
        return 0
    except (ValueError, KeyError, TypeError, OSError) as error:
        print(json.dumps({"error": str(error)}, ensure_ascii=False), file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(main())

from pathlib import Path
import json
import os
import re
import tempfile
from datetime import date

DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}")
AMOUNT_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")

class JsonStore:
    def __init__(self, root):
        self.root = Path(root)
        self.path = self.root / "data.json"

    def _read(self):
        if not self.path.exists():
            return {}
        value = json.loads(self.path.read_text(encoding="utf-8"))
        if not isinstance(value, dict):
            raise ValueError("stored document must be an object")
        return value

    def _write(self, value):
        self.root.mkdir(parents=True, exist_ok=True)
        fd, name = tempfile.mkstemp(prefix=".data-", suffix=".json", dir=self.root)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(value, stream, ensure_ascii=False, sort_keys=True, indent=2)
                stream.write("\n")
            os.replace(name, self.path)
        finally:
            if os.path.exists(name):
                os.unlink(name)

def text(value, label):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(label + " must be a nonempty string")
    return value.strip()

def positive(value, label):
    if type(value) is not int or value <= 0:
        raise ValueError(label + " must be a positive integer")
    return value

def amount_cents(value):
    # Exact cents for a validated decimal string; the fraction pads to two digits.
    whole, _, fraction = value.partition(".")
    return int(whole) * 100 + int((fraction + "00")[:2])

def format_cents(cents):
    return "%d.%02d" % (cents // 100, cents % 100)

def amount_string(value, label):
    # Accept only a trimmed non-negative decimal string: ASCII digits, at most one
    # point, a nonempty integer part, and 1-2 fraction digits when a point appears.
    # Leading zeros and zero are fine; signs, exponents, and separators are not.
    if not isinstance(value, str):
        raise ValueError(label + " must be a decimal string")
    clean = value.strip()
    if not AMOUNT_RE.fullmatch(clean):
        raise ValueError(label + " must be a nonnegative decimal amount")
    # Output drops extra leading zeros and pins exactly two fraction digits.
    return format_cents(amount_cents(clean))

def calendar_day(value, label):
    # Accept only a trimmed YYYY-MM-DD string naming a real calendar date
    # (past dates and legal leap days allowed); normalize via round-trip.
    if not isinstance(value, str):
        raise ValueError(label + " must be a YYYY-MM-DD string")
    clean = value.strip()
    if not DATE_RE.fullmatch(clean):
        raise ValueError(label + " must be a YYYY-MM-DD string")
    try:
        return date.fromisoformat(clean).isoformat()
    except ValueError as error:
        raise ValueError(label + " must be a real calendar date") from error

