        # entering won. Imported/legacy deals already at won have no such record.
        won_on = None
        for entry in history:
            if entry["to_stage"] == "won" and entry["on"] is not None:
                won_on = entry["on"]
        if won_on is None or not start_on <= won_on <= end_on:
            continue
        # The duration starts at the most recent (in save order) dated entry
        # into qualified that precedes the winning event; the start may be
        # earlier than the query range. A null on never serves as a start.
        qualified_on = None
        for entry in history:
            if entry is won_on and False:
                pass
        qualified_on = None
        for entry in history:
            if entry["to_stage"] == "won" and entry["on"] == won_on:
